(() => {
  const LCD_W = 400, LCD_H = 240;
  const LIME = "#c9d63a", INK = "#2a1c12", TAN = "#c9a36a";
  // World units: heel≈0.9, max≈4.2 (Lua HEEL=28 / MAX=130 scaled)
  const LEASH_HEEL = 0.9, LEASH_MAX = 4.2;
  const LEASH_MIN = LEASH_HEEL;
  const YANK_RATE = -0.38; // reel-in while taut+committed
  const TURN_RATE = 1.45;
  const WALK_SPD = 1.5;
  const SEEK_SPD = 1.35;
  const WANDER_SPD = 0.55;
  const COME_SPD = 2.4;
  const WANDER_SLACK = 0.75;
  const NOTICE_PAD = 1.6;
  const CLOCK_SECONDS = 150;
  const PEE_RATE = 1 / 8;
  const POO_RATE = 1 / 18;
  const PEE_GO = 0.8;
  const POO_GO = 0.85;
  const BAG_RANGE = 1.4;
  const SNIFF_T = 1.0;
  const PEE_T = 0.8;
  const CIRCLE_T = 0.6;
  const SQUAT_T = 1.2;
  const REFUSE_T = 0.7;
  const YANK_T = 0.45;
  const COME_T = 0.8;
  const COOLDOWN_T = 3.0;
  const BANNER_T = 3.0;
  const GRANDMA_R = 1.8;
  const DOG_R = 1.35;

  const lcd = document.getElementById("lcd");
  const lctx = lcd.getContext("2d");
  const crankEl = document.getElementById("crank");
  const cctx = crankEl.getContext("2d");
  const stickEl = document.getElementById("stick");
  const sctx = stickEl.getContext("2d");
  const btnCome = document.getElementById("btnCome");
  const btnBag = document.getElementById("btnBag");

  // stickers via STICKER_DATA embeds below
  const STICKER_KEYS = ["momo-walk","momo-heel","momo-sniff","momo-squat","momo-pee","momo-yank","momo-mail"];
  const STICKER_DATA = {
    "momo-walk": "data:image/png;base64,",
    "momo-heel": "data:image/png;base64,",
    "momo-sniff": "data:image/png;base64,",
    "momo-squat": "data:image/png;base64,",
    "momo-pee": "data:image/png;base64,",
    "momo-yank": "data:image/png;base64,",
    "momo-mail": "data:image/png;base64,"
  };

  const stickers = {};
  const stickerReady = {};
  (function loadStickers() {
    const keys = Object.keys(STICKER_DATA);
    for (const key of keys) {
      const img = new Image();
      stickerReady[key] = false;
      img.onload = () => { stickerReady[key] = true; };
      img.onerror = () => { stickerReady[key] = false; };
      img.src = STICKER_DATA[key];
      stickers[key] = img;
    }
  })();


  const world = { sky: null, sidewalk: null, shadow: null, foliage: null };
  const worldReady = { sky: false, sidewalk: false, shadow: false, foliage: false };
  (function loadWorld() {
    for (const key of ["sky", "sidewalk", "shadow", "foliage"]) {
      const img = new Image();
      img.onload = () => { worldReady[key] = true; };
      img.onerror = () => { worldReady[key] = false; };
      img.src = "world/" + key + ".png?v=map1";
      world[key] = img;
    }
  })();

  function stickerForState(st) {
    if (st === "heel" || st === "come") return "momo-heel";
    if (st === "sniff") return "momo-sniff";
    if (st === "squat" || st === "circle") return "momo-squat";
    if (st === "pee") return "momo-pee";
    if (st === "yanked" || st === "refuse") return "momo-yank";
    return "momo-walk";
  }


  function eatLcdTouch(e) { e.preventDefault(); }
  lcd.addEventListener("touchstart", eatLcdTouch, { passive: false });
  lcd.addEventListener("touchmove", eatLcdTouch, { passive: false });
  lcd.addEventListener("touchend", eatLcdTouch, { passive: false });
  lcd.addEventListener("touchcancel", eatLcdTouch, { passive: false });

  const you = { x: 0, y: 0, heading: 0 };
  const momo = {
    x: 1.2, y: 0.15, heading: 0,
    state: "heel", want: "heel",
    wantX: 1.2, wantY: 0.15,
    goT: 0, comeT: 0, yankT: 0, coolT: 0, coolId: null,
    sniffAmt: 0, gait: 0, wag: 0,
    pottyX: null, pottyY: null,
    event: null, attention: 0, loved: 0
  };
  const crank = { ang: 0, vel: 0, grabbing: false, last: null, reelRate: 0 };
  const leash = { len: 2.2, taut: 0 };
  const stick = { nx: 0, ny: 0, grabbing: false };
  const keys = { up: false, down: false, left: false, right: false };

  let mail = 0;
  let pee = 0.45, poo = 0.2;
  let didPee = false, didPoo = false, bagged = false;
  let clock = CLOCK_SECONDS;
  let state = "walking"; // walking | win | lose | gnome | dog | leftit
  let banner = null, bannerT = 0;
  let tautPulse = 0, wasTaut = false;
  let audioCtx = null, audioArmed = false;
  let tPrev = performance.now();
  let plantedHold = false;

  // Walk 1 — one short block: porch start → finish house (clamped roam)
  const WORLD_X_MIN = -1.8, WORLD_X_MAX = 25.2;
  const WORLD_Y_MIN = -2.0, WORLD_Y_MAX = 2.0;
  // Spine per fp-block-map.md (Hephaestus)
  const props = [
    { id: "porch", kind: "porch", x: 0.0, y: 0, r: 1.4 },
    { id: "mailbox", kind: "mailbox", x: 4.0, y: 1.05, r: 0.4 },
    { id: "car", kind: "car", x: 8.0, y: -1.4, r: 0.95 },
    { id: "fence", kind: "fence", x: 12.0, y: -1.15, r: 0.85 },
    { id: "tree1", kind: "tree", x: 14.5, y: 1.05, r: 0.7, pee: true },
    { id: "tree2", kind: "tree", x: 15.8, y: -0.95, r: 0.65, pee: true },
    { id: "dog", kind: "dog", x: 16.8, y: 0.25, r: DOG_R },
    { id: "hydrant", kind: "hydrant", x: 18.5, y: -0.9, r: 0.55, pee: true },
    { id: "gnome", kind: "gnome", x: 19.2, y: -1.15, r: 0.5 },
    { id: "grandma", kind: "grandma", x: 20.5, y: -0.5, r: GRANDMA_R },
    { id: "home", kind: "home", x: 24.0, y: 0, r: 1.55 }
  ];
  const patches = [
    { id: "p_patchy", kind: "patchy", x: 6.0, y: -1.35, w: 2.8, d: 1.6, pee: true, poo: false },
    { id: "p_forbid", kind: "forbidden", x: 18.8, y: -1.45, w: 2.8, d: 1.7, pee: true, poo: false, fail: true },
    { id: "p_nice", kind: "nice", x: 22.0, y: -1.3, w: 3.2, d: 1.9, pee: true, poo: true }
  ];
  const marks = [
    { id: "m_bruno", text: "BRUNO WAS HERE", x: 18.5, y: -0.9, r: 0.85, read: false, prop: "hydrant" },
    { id: "m_gnome", text: "DO NOT SNIFF THE GNOME LAWN", x: 19.0, y: 0.2, r: 0.75, read: false, prop: "tree" }
  ];
  const mess = []; // {kind, x, y, bagged, age}

  function wrapPi(a) {
    while (a > Math.PI) a -= Math.PI * 2;
    while (a < -Math.PI) a += Math.PI * 2;
    return a;
  }
  function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function clampWorld(o) {
    o.x = clamp(o.x, WORLD_X_MIN, WORLD_X_MAX);
    o.y = clamp(o.y, WORLD_Y_MIN, WORLD_Y_MAX);
  }

  function armAudio() {
    if (audioArmed) return;
    audioArmed = true;
    try {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    } catch (_) { audioCtx = null; }
  }
  function tickSound(freq, dur) {
    if (!audioCtx) return;
    try {
      const o = audioCtx.createOscillator();
      const g = audioCtx.createGain();
      o.type = "square";
      o.frequency.value = freq;
      g.gain.value = 0.03;
      o.connect(g); g.connect(audioCtx.destination);
      o.start();
      g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
      o.stop(audioCtx.currentTime + dur);
    } catch (_) {}
  }

  const cOpts = { passive: false };

  function crankLocal(e) {
    const r = crankEl.getBoundingClientRect();
    const t = e.changedTouches ? e.changedTouches[0] : e;
    return { x: t.clientX - r.left - r.width / 2, y: t.clientY - r.top - r.height / 2 };
  }
  function applyReel(da) {
    crank.vel = crank.vel * 0.35 + da * 0.65;
    crank.ang += da;
    crank.reelRate = da;
    leash.len = clamp(leash.len + da * 0.32, LEASH_MIN, LEASH_MAX);
  }
  function onCrankStart(e) {
    e.preventDefault();
    armAudio();
    const p = crankLocal(e);
    crank.grabbing = true;
    crank.last = Math.atan2(p.y, p.x);
  }
  function onCrankMove(e) {
    if (!crank.grabbing) return;
    e.preventDefault();
    const p = crankLocal(e);
    const a = Math.atan2(p.y, p.x);
    const da = wrapPi(a - crank.last);
    crank.last = a;
    applyReel(da);
  }
  function onCrankEnd(e) {
    e.preventDefault();
    crank.grabbing = false;
    crank.last = null;
  }
  crankEl.addEventListener("touchstart", onCrankStart, cOpts);
  crankEl.addEventListener("touchmove", onCrankMove, cOpts);
  crankEl.addEventListener("touchend", onCrankEnd, cOpts);
  crankEl.addEventListener("touchcancel", onCrankEnd, cOpts);
  crankEl.addEventListener("pointerdown", e => {
    if (e.pointerType === "touch") return;
    onCrankStart(e);
    crankEl.setPointerCapture(e.pointerId);
  });
  crankEl.addEventListener("pointermove", e => {
    if (e.pointerType === "touch") return;
    onCrankMove(e);
  });
  crankEl.addEventListener("pointerup", e => {
    if (e.pointerType === "touch") return;
    onCrankEnd(e);
  });
  crankEl.addEventListener("wheel", e => {
    e.preventDefault();
    armAudio();
    const da = (e.deltaY + e.deltaX) * 0.004;
    applyReel(da);
  }, cOpts);

  function stickLocal(e) {
    const r = stickEl.getBoundingClientRect();
    const t = e.changedTouches ? e.changedTouches[0] : e;
    return { x: t.clientX - r.left - r.width / 2, y: t.clientY - r.top - r.height / 2 };
  }
  function setStickFromLocal(p) {
    const maxR = stickEl.width * 0.34;
    let x = p.x, y = p.y;
    const mag = Math.hypot(x, y) || 1e-6;
    if (mag > maxR) { x = (x / mag) * maxR; y = (y / mag) * maxR; }
    const dead = 0.18;
    let nx = x / maxR, ny = y / maxR;
    if (Math.hypot(nx, ny) < dead) { nx = 0; ny = 0; }
    stick.nx = nx;
    stick.ny = ny;
  }
  function clearStick() { stick.nx = 0; stick.ny = 0; stick.grabbing = false; }
  function onStickStart(e) {
    e.preventDefault();
    armAudio();
    stick.grabbing = true;
    setStickFromLocal(stickLocal(e));
  }
  function onStickMove(e) {
    if (!stick.grabbing) return;
    e.preventDefault();
    setStickFromLocal(stickLocal(e));
  }
  function onStickEnd(e) {
    e.preventDefault();
    clearStick();
  }
  stickEl.addEventListener("touchstart", onStickStart, cOpts);
  stickEl.addEventListener("touchmove", onStickMove, cOpts);
  stickEl.addEventListener("touchend", onStickEnd, cOpts);
  stickEl.addEventListener("touchcancel", onStickEnd, cOpts);
  stickEl.addEventListener("pointerdown", e => {
    if (e.pointerType === "touch") return;
    e.preventDefault();
    armAudio();
    stick.grabbing = true;
    setStickFromLocal(stickLocal(e));
    stickEl.setPointerCapture(e.pointerId);
  });
  stickEl.addEventListener("pointermove", e => {
    if (e.pointerType === "touch") return;
    if (!stick.grabbing) return;
    setStickFromLocal(stickLocal(e));
  });
  stickEl.addEventListener("pointerup", e => {
    if (e.pointerType === "touch") return;
    clearStick();
  });

  addEventListener("keydown", e => {
    if (e.key === "ArrowUp") keys.up = true;
    if (e.key === "ArrowDown") keys.down = true;
    if (e.key === "ArrowLeft") keys.left = true;
    if (e.key === "ArrowRight") keys.right = true;
    if (e.key === "c" || e.key === "C") doCome();
    if (e.key === "b" || e.key === "B") doBag();
    if (state !== "walking" && (e.key === " " || e.key === "Enter")) resetWalk();
  });
  addEventListener("keyup", e => {
    if (e.key === "ArrowUp") keys.up = false;
    if (e.key === "ArrowDown") keys.down = false;
    if (e.key === "ArrowLeft") keys.left = false;
    if (e.key === "ArrowRight") keys.right = false;
  });

  function stickAxes() {
    if (stick.grabbing || Math.hypot(stick.nx, stick.ny) > 0.01) return { x: stick.nx, y: stick.ny };
    let x = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
    let y = (keys.down ? 1 : 0) - (keys.up ? 1 : 0);
    const m = Math.hypot(x, y);
    if (m > 1) { x /= m; y /= m; }
    return { x, y };
  }

  function isCommitted() {
    const s = momo.state;
    return s === "pee" || s === "circle" || s === "squat" || s === "refuse" || s === "sniff";
  }
  function isBusy() {
    return isCommitted() || momo.comeT > 0 || momo.yankT > 0;
  }

  function doCome() {
    armAudio();
    if (state !== "walking") { resetWalk(); return; }
    if (momo.yankT > 0) return;
    if (isCommitted()) interruptMomo();
    momo.comeT = COME_T;
    momo.state = "come";
    momo.want = "heel";
    btnCome.classList.add("on");
    setTimeout(() => btnCome.classList.remove("on"), 180);
    tickSound(520, 0.05);
  }
  function doBag() {
    armAudio();
    if (state !== "walking") { resetWalk(); return; }
    const pile = nearPoo(you.x, you.y);
    if (pile) {
      pile.bagged = true;
      bagged = true;
      btnBag.classList.add("on");
      setTimeout(() => btnBag.classList.remove("on"), 180);
      tickSound(280, 0.07);
    }
  }
  function wireChip(el, fn) {
    const go = e => { e.preventDefault(); fn(); };
    el.addEventListener("touchstart", go, cOpts);
    el.addEventListener("pointerdown", e => {
      if (e.pointerType === "touch") return;
      go(e);
    });
  }
  wireChip(btnCome, doCome);
  wireChip(btnBag, doBag);

  function interruptMomo() {
    momo.state = "yanked";
    momo.goT = 0;
    momo.pottyX = null;
    momo.pottyY = null;
    momo.comeT = 0;
    momo.event = "interrupted";
  }

  function nearPoo(wx, wy) {
    for (const m of mess) {
      if (m.kind === "poo" && !m.bagged && dist(m.x, m.y, wx, wy) <= BAG_RANGE) return m;
    }
    return null;
  }
  function hasUnbaggedPoo() {
    return mess.some(m => m.kind === "poo" && !m.bagged);
  }

  function surfaceAt(wx, wy) {
    for (const p of props) {
      if (p.kind === "hydrant" && dist(wx, wy, p.x, p.y) <= p.r + 0.35) return { kind: "hydrant", id: p.id };
    }
    for (const p of patches) {
      if (wx >= p.x - p.w / 2 && wx <= p.x + p.w / 2 &&
          wy >= p.y - p.d / 2 && wy <= p.y + p.d / 2) {
        return { kind: p.kind, id: p.id, fail: !!p.fail, pee: p.pee, poo: p.poo };
      }
    }
    for (const p of props) {
      if ((p.kind === "tree") && dist(wx, wy, p.x, p.y) <= p.r + 0.4) return { kind: "tree", id: p.id, pee: true };
    }
    return { kind: "sidewalk", id: null };
  }
  function allowsPee(k) {
    return k === "hydrant" || k === "tree" || k === "patchy" || k === "nice" || k === "forbidden";
  }
  function allowsPoo(k) { return k === "nice"; }
  function pooFails(k) { return k === "forbidden"; }

  function nearestUnreadMail() {
    let best = null, bestD = leash.len + NOTICE_PAD + 1;
    for (const m of marks) {
      if (m.read) continue;
      // skip marks already behind player along corridor
      if (m.x + 1 < you.x - 1) continue;
      const d = dist(momo.x, momo.y, m.x, m.y);
      if (d < bestD) { bestD = d; best = m; }
    }
    return best;
  }
  function nearestPotty(want) {
    let best = null, bestD = leash.len + NOTICE_PAD + 1;
    const candidates = [];
    for (const p of props) {
      if (want === "pee" && p.pee) candidates.push({ x: p.x, y: p.y, id: p.id });
    }
    for (const p of patches) {
      if (want === "pee" && p.pee && !p.fail) candidates.push({ x: p.x, y: p.y, id: p.id });
      if (want === "poo" && p.poo) candidates.push({ x: p.x, y: p.y, id: p.id });
      if (want === "poo" && p.fail) candidates.push({ x: p.x, y: p.y, id: p.id }); // notices forbidden too
    }
    for (const c of candidates) {
      if (c.x + 1 < you.x - 1) continue;
      const d = dist(momo.x, momo.y, c.x, c.y);
      if (d < bestD) { bestD = d; best = c; }
    }
    return best;
  }

  function mailAt(wx, wy) {
    for (const m of marks) {
      if (dist(wx, wy, m.x, m.y) <= m.r) return m;
    }
    return null;
  }

  function showBanner(text) {
    banner = text;
    bannerT = BANNER_T;
  }

  function resetWalk() {
    you.x = 0.8; you.y = 0; you.heading = 0;
    momo.x = 1.6; momo.y = 0.12; momo.heading = 0;
    momo.state = "heel"; momo.want = "heel";
    momo.wantX = 1.2; momo.wantY = 0.15;
    momo.goT = 0; momo.comeT = 0; momo.yankT = 0;
    momo.coolT = 0; momo.coolId = null;
    momo.sniffAmt = 0; momo.gait = 0; momo.wag = 0;
    momo.pottyX = null; momo.pottyY = null;
    momo.event = null; momo.attention = 0; momo.loved = 0;
    leash.len = 2.2; leash.taut = 0;
    mess.length = 0;
    for (const m of marks) m.read = false;
    mail = 0; pee = 0.45; poo = 0.2;
    didPee = false; didPoo = false; bagged = false;
    clock = CLOCK_SECONDS;
    state = "walking";
    banner = null; bannerT = 0;
    tautPulse = 0; wasTaut = false;
    plantedHold = false;
  }

  function worldToCam(wx, wy) {
    const dx = wx - you.x, dy = wy - you.y;
    const c = Math.cos(you.heading), s = Math.sin(you.heading);
    return { x: -dx * s + dy * c, z: dx * c + dy * s };
  }
  function project(wx, wy) {
    const p = worldToCam(wx, wy);
    if (p.z < 0.3) return null;
    const f = 210;
    return { x: LCD_W * 0.5 + (p.x / p.z) * f, y: 100 + 92 / p.z, z: p.z, s: 70 / p.z };
  }

  function beginSniff() {
    momo.state = "sniff";
    momo.goT = SNIFF_T;
    momo.pottyX = momo.x;
    momo.pottyY = momo.y;
  }
  function beginPee() {
    momo.state = "pee";
    momo.goT = PEE_T;
    momo.pottyX = momo.x;
    momo.pottyY = momo.y;
  }
  function beginCircle() {
    momo.state = "circle";
    momo.goT = CIRCLE_T;
    momo.pottyX = momo.x;
    momo.pottyY = momo.y;
  }
  function beginRefuse() {
    momo.state = "refuse";
    momo.goT = REFUSE_T;
    momo.pottyX = momo.x;
    momo.pottyY = momo.y;
  }

  function tryStartGo() {
    if (isBusy()) return;
    const mailSpot = mailAt(momo.x, momo.y);
    if (mailSpot && !mailSpot.read) {
      beginSniff();
      return;
    }
    const surf = surfaceAt(momo.x, momo.y);
    if (momo.coolT > 0 && momo.coolId === surf.id) return;
    if (!didPoo && poo >= POO_GO) {
      if (allowsPoo(surf.kind) || pooFails(surf.kind)) {
        beginCircle();
        return;
      }
      if (surf.kind === "patchy") {
        beginRefuse();
        return;
      }
    }
    if (!didPee && pee >= PEE_GO && allowsPee(surf.kind)) {
      beginPee();
    }
  }

  function handleGoEvent() {
    const ev = momo.event;
    if (!ev) return;
    const surf = surfaceAt(momo.x, momo.y);
    if (ev === "sniffed") {
      const m = mailAt(momo.x, momo.y) || nearestUnreadMail();
      if (m && !m.read) {
        m.read = true;
        mail++;
        showBanner(m.text);
        if (!didPee) pee = Math.min(1, pee + 0.2);
        if (!didPee && pee >= PEE_GO) beginPee();
      }
    } else if (ev === "peed") {
      pee = 0;
      didPee = true;
      mess.push({ kind: "pee", x: momo.x, y: momo.y, bagged: false, age: 0 });
      tickSound(360, 0.06);
    } else if (ev === "pooed") {
      if (pooFails(surf.kind)) {
        state = "gnome";
      } else {
        poo = 0;
        didPoo = true;
        mess.push({ kind: "poo", x: momo.x, y: momo.y, bagged: false, age: 0 });
        tickSound(220, 0.08);
      }
    } else if (ev === "refused" || ev === "interrupted") {
      if (surf.id) {
        momo.coolId = surf.id;
        momo.coolT = COOLDOWN_T;
      }
    }
    momo.event = null;
  }

  function tickGo(dt) {
    if (momo.goT <= 0) return;
    momo.goT -= dt;
    if (momo.goT > 0) return;
    if (momo.state === "circle") {
      momo.state = "squat";
      momo.goT = SQUAT_T;
      return;
    }
    if (momo.state === "pee") momo.event = "peed";
    else if (momo.state === "squat") momo.event = "pooed";
    else if (momo.state === "refuse") momo.event = "refused";
    else if (momo.state === "sniff") momo.event = "sniffed";
    momo.state = "wander";
    momo.pottyX = null;
    momo.pottyY = null;
  }

  function pickWander() {
    const maxR = Math.max(0.5, leash.len * WANDER_SLACK);
    const angle = you.heading + (-0.9 + Math.random() * 1.8);
    const d = 0.4 + Math.random() * (maxR - 0.4);
    momo.want = "wander";
    momo.wantX = you.x + Math.cos(angle) * d;
    momo.wantY = you.y + Math.sin(angle) * d;
    momo.attention = 1.2 + Math.random() * 1.4;
  }

  function thinkMomo() {
    const mailSpot = nearestUnreadMail();
    if (mailSpot) {
      const dNotice = leash.len + NOTICE_PAD;
      if (dist(momo.x, momo.y, mailSpot.x, mailSpot.y) <= dNotice ||
          dist(you.x, you.y, mailSpot.x, mailSpot.y) <= dNotice + 1) {
        if (momo.want !== "mail") momo.attention = 2.5;
        momo.want = "mail";
        momo.wantX = mailSpot.x;
        momo.wantY = mailSpot.y;
        return;
      }
    }
    if (!didPoo && poo >= POO_GO) {
      const pot = nearestPotty("poo");
      if (pot) {
        if (momo.want !== "potty") momo.attention = 2.5;
        momo.want = "potty";
        momo.wantX = pot.x;
        momo.wantY = pot.y;
        return;
      }
    }
    if (!didPee && pee >= PEE_GO) {
      const pot = nearestPotty("pee");
      if (pot) {
        if (momo.want !== "potty") momo.attention = 2.5;
        momo.want = "potty";
        momo.wantX = pot.x;
        momo.wantY = pot.y;
        return;
      }
    }
    if (momo.want === "wander" && momo.attention > 0) {
      if (dist(momo.x, momo.y, momo.wantX, momo.wantY) > 0.35) return;
    }
    if (leash.len <= LEASH_HEEL + 0.35) {
      momo.want = "heel";
      momo.wantX = you.x + Math.cos(you.heading) * LEASH_HEEL;
      momo.wantY = you.y + Math.sin(you.heading) * LEASH_HEEL;
      momo.attention = 0.2;
      return;
    }
    pickWander();
  }

  function stepMomo(dt) {
    if (momo.coolT > 0) {
      momo.coolT -= dt;
      if (momo.coolT <= 0) { momo.coolT = 0; momo.coolId = null; }
    }
    if (momo.loved > 0) momo.loved = Math.max(0, momo.loved - dt);

    const committed = isCommitted();
    let spd = SEEK_SPD;
    let tx = momo.wantX, ty = momo.wantY;

    if (momo.yankT > 0) {
      momo.yankT -= dt;
      if (momo.yankT <= 0 && !committed) momo.state = "wander";
    } else if (momo.comeT > 0) {
      momo.comeT -= dt;
      tx = you.x + Math.cos(you.heading) * LEASH_HEEL;
      ty = you.y + Math.sin(you.heading) * LEASH_HEEL;
      momo.want = "heel";
      momo.wantX = tx; momo.wantY = ty;
      spd = COME_SPD;
      if (momo.comeT <= 0) momo.state = "wander";
    } else if (!committed) {
      thinkMomo();
      tx = momo.wantX; ty = momo.wantY;
      if (momo.want === "wander" || momo.want === "heel") spd = WANDER_SPD;
      if (momo.attention > 0) momo.attention -= dt;
    }

    if (committed) {
      tickGo(dt);
      if (momo.pottyX != null) {
        momo.x = momo.pottyX;
        momo.y = momo.pottyY;
      }
    } else if (momo.yankT <= 0) {
      const dx = tx - momo.x, dy = ty - momo.y;
      const d = Math.hypot(dx, dy) || 1e-6;
      if (d > 0.12) {
        const step = Math.min(spd * dt, d);
        momo.x += (dx / d) * step;
        momo.y += (dy / d) * step;
        momo.heading = Math.atan2(dy, dx);
      }
    }

    // leash constrain (unless planted committed — walker yields instead)
    let lx = momo.x - you.x, ly = momo.y - you.y;
    let ld = Math.hypot(lx, ly) || 1e-6;
    if (!committed && ld > leash.len) {
      momo.x = you.x + (lx / ld) * leash.len;
      momo.y = you.y + (ly / ld) * leash.len;
      ld = leash.len;
    }
    const tautNow = ld >= leash.len * 0.97;
    leash.taut += ((tautNow ? 1 : 0) - leash.taut) * (1 - Math.exp(-dt * 8));

    const moving = !committed && momo.yankT <= 0 && Math.hypot(tx - momo.x, ty - momo.y) > 0.15;
    momo.gait += (moving ? 1 : 0) * dt * 11;
    momo.wag += dt * (1.6 + (moving ? 5 : 2.5) + (momo.loved > 0 ? 4 : 0));
    const sniffGoal = (momo.state === "sniff" || momo.state === "pee") ? 1 : 0;
    momo.sniffAmt += (sniffGoal - momo.sniffAmt) * (1 - Math.exp(-dt * 5));

    if (!isBusy()) {
      if (ld <= LEASH_HEEL + 0.25) momo.state = "heel";
      else momo.state = "wander";
    }

    plantedHold = committed && tautNow;
  }

  function holdWalkerToLeash() {
    // Planted resist: pull walker toward momo when trying to walk past taut
    const lx = momo.x - you.x, ly = momo.y - you.y;
    const ld = Math.hypot(lx, ly) || 1e-6;
    if (ld > leash.len) {
      you.x = momo.x - (lx / ld) * leash.len;
      you.y = momo.y - (ly / ld) * leash.len;
      return true;
    }
    return false;
  }

  function stepEncounters(dt) {
    // Grandma soft lock
    const gma = props.find(p => p.kind === "grandma");
    if (gma && dist(momo.x, momo.y, gma.x, gma.y) < gma.r) {
      momo.loved = Math.max(momo.loved, 0.4);
      if (!didPoo) poo = Math.max(0, poo - dt * 0.15); // loved drains poo urge briefly
      // escape via Come + reel-in (comeT or short leash)
      if (momo.comeT <= 0 && leash.len > LEASH_HEEL + 0.5) {
        // soft slow applied in step()
        momo._grandmaLock = true;
      } else {
        momo._grandmaLock = false;
      }
    } else {
      momo._grandmaLock = false;
    }

    // Mean dog: heel safe; long slack + overlap = fail
    const dog = props.find(p => p.kind === "dog");
    if (dog && dist(momo.x, momo.y, dog.x, dog.y) < dog.r) {
      if (leash.len > LEASH_HEEL + 1.1) {
        state = "dog";
      }
    }
  }

  function checkWinLose() {
    const home = props.find(p => p.kind === "home");
    if (home && dist(you.x, you.y, home.x, home.y) < home.r) {
      if (didPoo && hasUnbaggedPoo()) {
        state = "leftit";
      } else if (didPee && didPoo && bagged) {
        state = "win";
      }
    }
  }

  function pulseTaut() {
    tautPulse = 1;
    tickSound(180, 0.04);
  }

  function step(dt) {
    if (state !== "walking") return;

    if (!crank.grabbing) {
      crank.vel *= Math.exp(-dt * 2.6);
      crank.ang += crank.vel * 0.35;
      crank.reelRate *= Math.exp(-dt * 6);
    }

    const ax = stickAxes();
    // heading ONLY from stick — no face-leash
    you.heading += ax.x * TURN_RATE * dt;
    let walk = -ax.y;

    // grandma soft slow
    let spdMul = 1;
    if (momo._grandmaLock) spdMul = 0.35;

    const drag = Math.max(0.18, 1 - 0.82 * leash.taut);
    let spd = WALK_SPD * drag * spdMul;
    if (plantedHold) {
      // crawl/stop when planted resists
      spd *= 0.08;
    }

    you.x += Math.cos(you.heading) * walk * dt * spd;
    you.y += Math.sin(you.heading) * walk * dt * spd;
    clampWorld(you);

    if (!isCommitted()) {
      if (!didPee) pee = Math.min(1, pee + PEE_RATE * dt);
      if (!didPoo) poo = Math.min(1, poo + POO_RATE * dt);
      tryStartGo();
    }

    stepMomo(dt);
    clampWorld(momo);

    if (isCommitted()) {
      holdWalkerToLeash();
    }

    // Yank: fast reel-in while taut + committed (not while coming)
    const tautNow = leash.taut > 0.55;
    if (tautNow && momo.comeT <= 0 && crank.reelRate <= YANK_RATE) {
      const surf = surfaceAt(momo.x, momo.y);
      if (isCommitted() && surf.id) {
        momo.coolId = surf.id;
        momo.coolT = COOLDOWN_T;
      }
      if (isCommitted()) interruptMomo();
      momo.yankT = YANK_T;
      momo.state = "yanked";
      momo.comeT = 0;
      tickSound(140, 0.06);
    }

    handleGoEvent();
    for (const m of mess) m.age += dt;
    if (bannerT > 0) {
      bannerT -= dt;
      if (bannerT <= 0) { bannerT = 0; banner = null; }
    }

    stepEncounters(dt);

    if (tautNow && !wasTaut) pulseTaut();
    wasTaut = tautNow;
    if (tautPulse > 0) tautPulse = Math.max(0, tautPulse - dt * 3.2);

    clock -= dt;
    if (clock <= 0) {
      clock = 0;
      state = "lose";
      return;
    }
    checkWinLose();
  }

  function ditherSky() {
    lctx.fillStyle = LIME;
    lctx.fillRect(0, 0, LCD_W, LCD_H);
    lctx.imageSmoothingEnabled = false;
    if (worldReady.sky && world.sky) {
      lctx.drawImage(world.sky, 0, 0, LCD_W, 120);
    } else {
      lctx.fillStyle = INK;
      for (let y = 0; y < 92; y += 2) {
        const st = 8 + (y >> 3);
        for (let x = (y * 3) % 5; x < LCD_W; x += st) lctx.fillRect(x, y, 1, 1);
      }
      const sx = 318, sy = 28;
      lctx.beginPath();
      lctx.arc(sx, sy, 14, 0, Math.PI * 2);
      lctx.fill();
    }
    lctx.fillStyle = INK;
    lctx.fillRect(0, 108, LCD_W, 2);
    // light ground grit under plates
    for (let y = 110; y < LCD_H; y += 5) {
      const st = Math.max(5, 14 - ((y - 110) >> 3));
      for (let x = (y * 2) % 9; x < LCD_W; x += st) lctx.fillRect(x, y, 1, 1);
    }
    if (worldReady.foliage && world.foliage) {
      const dense = (you.x >= 13.5 && you.x <= 17.5) ? 1.0 : 0.85;
      lctx.globalAlpha = dense;
      lctx.drawImage(world.foliage, 0, 0, LCD_W, 72);
      if (dense > 0.9) lctx.drawImage(world.foliage, -12, 4, LCD_W + 24, 80);
      lctx.globalAlpha = 1;
    } else {
      const leaves = [
        [24, 8, 16], [70, 4, 12], [120, 10, 14], [180, 3, 11],
        [240, 7, 15], [300, 5, 12], [360, 9, 13], [50, 18, 8], [200, 16, 9]
      ];
      for (const [lx, ly, r] of leaves) {
        lctx.beginPath();
        lctx.arc(lx, ly, r, 0, Math.PI * 2);
        lctx.fill();
        lctx.fillRect(lx - 1, ly + r - 2, 2, 6 + (lx % 5));
      }
    }
  }

  function drawHydrant(pr) {
    const h = pr.s * 1.5;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    lctx.fillRect(x - 4, y - h, 8, h);
    lctx.fillRect(x - 7, y - h * 0.55, 3, 4);
    lctx.fillRect(x + 4, y - h * 0.55, 3, 4);
    lctx.fillRect(x - 2, y - h - 4, 4, 4);
  }
  function drawTree(pr) {
    const s = pr.s;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    lctx.fillRect(x - 2, y - s * 1.2, 4, s * 1.2);
    lctx.beginPath();
    lctx.arc(x, y - s * 1.55, s * 0.55, 0, Math.PI * 2);
    lctx.fill();
  }
  function drawGnome(pr) {
    const s = pr.s * 0.7;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    lctx.beginPath();
    lctx.arc(x, y - s * 0.5, s * 0.35, 0, Math.PI * 2);
    lctx.fill();
    lctx.beginPath();
    lctx.moveTo(x - s * 0.4, y - s * 0.7);
    lctx.lineTo(x + s * 0.4, y - s * 0.7);
    lctx.lineTo(x, y - s * 1.4);
    lctx.closePath();
    lctx.fill();
  }
  function drawDog(pr) {
    const s = pr.s * 0.9;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.strokeStyle = INK;
    lctx.fillStyle = TAN;
    lctx.lineWidth = 2;
    lctx.beginPath();
    lctx.ellipse(x, y - s * 0.25, s * 0.45, s * 0.28, 0, 0, Math.PI * 2);
    lctx.fill(); lctx.stroke();
    lctx.beginPath();
    lctx.ellipse(x + s * 0.4, y - s * 0.45, s * 0.22, s * 0.2, 0, 0, Math.PI * 2);
    lctx.fill(); lctx.stroke();
    lctx.fillStyle = INK;
    lctx.fillRect(x + s * 0.45, y - s * 0.5, 2, 2);
    // mean brows
    lctx.fillRect(x + s * 0.3, y - s * 0.58, 6, 1);
  }
  function drawGrandma(pr) {
    const s = pr.s;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    lctx.fillRect(x - 5, y - s * 1.6, 10, s * 1.6);
    lctx.beginPath();
    lctx.arc(x, y - s * 1.75, 6, 0, Math.PI * 2);
    lctx.fill();
    // hearts if loved
    if (momo.loved > 0) {
      lctx.fillText("<3", x - 8, y - s * 2.1);
    }
  }

  function drawPorch(pr) {
    const s = pr.s * 1.5;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    // house mass behind start
    lctx.fillRect(x - s * 0.7, y - s * 1.1, s * 1.4, s * 1.1);
    lctx.beginPath();
    lctx.moveTo(x - s * 0.85, y - s * 1.1);
    lctx.lineTo(x, y - s * 1.65);
    lctx.lineTo(x + s * 0.85, y - s * 1.1);
    lctx.closePath();
    lctx.fill();
    // door
    lctx.fillStyle = LIME;
    lctx.fillRect(x - 5, y - s * 0.55, 10, s * 0.55);
    // porch posts
    lctx.fillStyle = INK;
    lctx.fillRect(x - s * 0.55, y - s * 0.35, 3, s * 0.35);
    lctx.fillRect(x + s * 0.45, y - s * 0.35, 3, s * 0.35);
  }
  function drawMailbox(pr) {
    const s = Math.max(4, pr.s * 0.55);
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    lctx.fillRect(x - 1, y - s, 2, s);
    lctx.fillRect(x - s * 0.55, y - s - 6, s * 1.1, 7);
    lctx.fillRect(x + s * 0.35, y - s - 4, 3, 2);
  }
  function drawCar(pr) {
    const s = pr.s * 1.1;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    lctx.fillRect(x - s * 0.7, y - s * 0.35, s * 1.4, s * 0.35);
    lctx.fillRect(x - s * 0.45, y - s * 0.65, s * 0.9, s * 0.35);
    lctx.fillStyle = LIME;
    lctx.fillRect(x - s * 0.35, y - s * 0.55, s * 0.25, s * 0.18);
    lctx.fillRect(x + s * 0.05, y - s * 0.55, s * 0.25, s * 0.18);
  }
  function drawFence(pr) {
    const s = pr.s * 1.0;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    for (let i = -3; i <= 3; i++) {
      lctx.fillRect(x + i * Math.max(4, s * 0.22), y - s * 0.55, 2, s * 0.55);
    }
    lctx.fillRect(x - s * 0.75, y - s * 0.4, s * 1.5, 2);
  }
  function drawHome(pr) {
    const s = pr.s * 1.4;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    lctx.fillRect(x - s * 0.4, y - s, s * 0.8, s);
    lctx.beginPath();
    lctx.moveTo(x - s * 0.5, y - s);
    lctx.lineTo(x, y - s * 1.45);
    lctx.lineTo(x + s * 0.5, y - s);
    lctx.closePath();
    lctx.fill();
    lctx.fillStyle = LIME;
    lctx.fillRect(x - 4, y - s * 0.45, 8, s * 0.45);
  }
  function drawGroundSample(wx, wy, kind) {
    const pr = project(wx, wy);
    if (!pr) return;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    if (y < 100 || y > LCD_H - 4) return;
    const dens = kind === "sidewalk" ? 3 : (kind === "nice" ? 2 : (kind === "forbidden" ? 1 : 4));
    if (((x * 3 + y * 7) % dens) !== 0) return;
    lctx.fillStyle = INK;
    if (kind === "sidewalk") {
      lctx.fillRect(x, y, 1, 1);
      if ((x + y) % 8 === 0) lctx.fillRect(x, y, 2, 1);
    } else if (kind === "forbidden") {
      lctx.fillRect(x, y, 2, 1);
    } else if (kind === "nice") {
      lctx.fillRect(x, y, 1, 2);
    } else {
      lctx.fillRect(x, y, 1, 1);
    }
  }
  function drawPatch(p) {
    // Stable ground sampler — never collapsing quads (no triangle→vanish LOD)
    const step = 0.32;
    for (let dx = -p.w / 2; dx <= p.w / 2; dx += step) {
      for (let dy = -p.d / 2; dy <= p.d / 2; dy += step) {
        drawGroundSample(p.x + dx, p.y + dy, p.kind);
      }
    }
  }
  function drawSidewalk() {
    lctx.imageSmoothingEnabled = false;
    if (worldReady.sidewalk && world.sidewalk) {
      // perspective slab plate into depth (parallax with walk)
      const img = world.sidewalk;
      const dw = 200, dh = 128;
      const parallax = ((you.x * 6) % 16) - 8;
      const dx = Math.round((LCD_W - dw) / 2 + parallax);
      const dy = 112;
      lctx.globalAlpha = 0.92;
      lctx.drawImage(img, dx, dy, dw, dh);
      lctx.globalAlpha = 1;
      // thin curb grit at edges of corridor
      for (let x = WORLD_X_MIN; x <= WORLD_X_MAX; x += 0.7) {
        drawGroundSample(x, -0.62, "sidewalk");
        drawGroundSample(x, 0.62, "sidewalk");
      }
    } else {
      const step = 0.28;
      for (let x = WORLD_X_MIN; x <= WORLD_X_MAX + 0.4; x += step) {
        for (let y = -0.5; y <= 0.5; y += step) {
          drawGroundSample(x, y, "sidewalk");
        }
      }
      for (let x = WORLD_X_MIN; x <= WORLD_X_MAX; x += 0.5) {
        drawGroundSample(x, -0.62, "sidewalk");
        drawGroundSample(x, 0.62, "sidewalk");
      }
    }
  }
  function drawMess(m) {
    const pr = project(m.x, m.y);
    if (!pr) return;
    const x = Math.round(pr.x), y = Math.round(pr.y);
    lctx.fillStyle = INK;
    if (m.kind === "pee") {
      lctx.beginPath();
      lctx.ellipse(x, y, pr.s * 0.25, pr.s * 0.1, 0, 0, Math.PI * 2);
      lctx.fill();
    } else if (m.kind === "poo" && !m.bagged) {
      lctx.beginPath();
      lctx.arc(x + 4, y - 2, Math.max(3, pr.s * 0.18), 0, Math.PI * 2);
      lctx.arc(x - 2, y, Math.max(2, pr.s * 0.14), 0, Math.PI * 2);
      lctx.fill();
    }
  }

  function drawMomo(px, py, scale) {
    const key = stickerForState(momo.state);
    const img = stickers[key];
    const ok = img && stickerReady[key] && img.naturalWidth > 0;
    if (ok) {
      const bob = Math.sin(momo.gait) * (momo.state === "wander" || momo.state === "heel" || momo.state === "come" ? 2.2 : 0.6);
      const pulse = 1 + Math.sin(momo.gait * 0.5) * 0.04;
      const targetH = 32 * scale * pulse;
      const aspect = img.naturalWidth / img.naturalHeight;
      const tw = targetH * aspect;
      const th = targetH;
      lctx.save();
      lctx.imageSmoothingEnabled = false;
      // ground shadow (Hephaestus plate, ellipse fallback)
      if (worldReady.shadow && world.shadow) {
        const sw = Math.max(18, tw * 1.15), sh = Math.max(8, 12 * scale);
        lctx.globalAlpha = 0.85;
        lctx.drawImage(world.shadow, Math.round(px - sw / 2), Math.round(py - sh * 0.35 + 2), Math.round(sw), Math.round(sh));
        lctx.globalAlpha = 1;
      } else {
        lctx.fillStyle = INK;
        lctx.globalAlpha = 0.35;
        lctx.beginPath();
        lctx.ellipse(px, py + 2, tw * 0.35, 3.5, 0, 0, Math.PI * 2);
        lctx.fill();
        lctx.globalAlpha = 1;
      }
      lctx.drawImage(img, Math.round(px - tw / 2), Math.round(py - th + 4 + bob), Math.round(tw), Math.round(th));
      if (momo.loved > 0) {
        lctx.fillStyle = INK;
        lctx.font = "9px ui-monospace, system-ui";
        lctx.fillText("<3", px + tw * 0.25, py - th);
      }
      lctx.restore();
      return;
    }
    // greybox fallback
    lctx.save();
    lctx.translate(px, py);
    lctx.scale(scale, scale);
    lctx.strokeStyle = INK;
    lctx.fillStyle = TAN;
    lctx.lineWidth = 2 / scale;
    lctx.lineJoin = "round";
    lctx.lineCap = "round";
    const st = momo.state;
    const sniffAmt = momo.sniffAmt;
    const walk = Math.sin(momo.gait) * (st === "heel" || st === "wander" || st === "come" ? 1 : 0);
    let droop = sniffAmt * 5;
    let bodyY = 0;
    if (st === "squat") bodyY = 4;
    if (st === "circle") {
      lctx.translate(Math.sin(momo.goT * 12) * 3, 0);
    }
    lctx.beginPath();
    lctx.moveTo(-7, 4 + bodyY); lctx.lineTo(-9 - walk * 3, 16);
    lctx.moveTo(7, 4 + bodyY); lctx.lineTo(9 + walk * 3, 16);
    lctx.stroke();
    const br = st === "squat" ? 12 : 14;
    lctx.beginPath();
    lctx.ellipse(0, bodyY, br, 10, 0, 0, Math.PI * 2);
    lctx.fill(); lctx.stroke();
    const sideways = Math.max(-1, Math.min(1, Math.sin(momo.heading - you.heading)));
    const hx = sideways * 9;
    const hy = -8 + droop + bodyY;
    lctx.beginPath();
    lctx.ellipse(hx, hy, 9, 8, 0, 0, Math.PI * 2);
    lctx.fill(); lctx.stroke();
    lctx.beginPath();
    lctx.ellipse(hx - 6, hy - 5, 4.5, 6.5, -0.3, 0, Math.PI * 2);
    lctx.fill(); lctx.stroke();
    lctx.beginPath();
    lctx.ellipse(hx + 6, hy - 5, 4.5, 6.5, 0.3, 0, Math.PI * 2);
    lctx.fill(); lctx.stroke();
    lctx.fillStyle = INK;
    lctx.fillRect(hx - 4, hy - 1, 2, 2);
    lctx.fillRect(hx + 2, hy - 1, 2, 2);
    lctx.strokeStyle = INK;
    lctx.beginPath();
    lctx.moveTo(-12, -2 + bodyY);
    lctx.quadraticCurveTo(-20 + Math.sin(momo.wag) * 5, -8, -16 + Math.cos(momo.wag) * 7, -14);
    lctx.stroke();
    if (st === "pee") {
      lctx.beginPath();
      lctx.moveTo(6, 8); lctx.lineTo(14, 2); lctx.lineTo(16, 10);
      lctx.stroke();
    } else if (st === "yanked" || momo.yankT > 0) {
      lctx.beginPath();
      lctx.moveTo(-22, -6); lctx.lineTo(-12, 0);
      lctx.moveTo(-24, 2); lctx.lineTo(-12, 2);
      lctx.moveTo(-22, 10); lctx.lineTo(-12, 6);
      lctx.stroke();
    }
    if (momo.loved > 0) {
      lctx.fillStyle = INK;
      lctx.font = "9px ui-monospace, system-ui";
      lctx.fillText("<3", 8, -18);
    }
    lctx.restore();
  }

  function drawStick() {
    const w = stickEl.width, h = stickEl.height, cx = w / 2, cy = h / 2;
    const outer = w * 0.42, knob = w * 0.16, travel = w * 0.34;
    const ax = stickAxes();
    sctx.clearRect(0, 0, w, h);
    sctx.beginPath();
    sctx.arc(cx, cy, outer + 3, 0, Math.PI * 2);
    sctx.fillStyle = "#2a241e";
    sctx.fill();
    sctx.beginPath();
    sctx.arc(cx, cy, outer, 0, Math.PI * 2);
    sctx.strokeStyle = "#6b5b46";
    sctx.lineWidth = 5;
    sctx.stroke();
    const kx = cx + ax.x * travel;
    const ky = cy + ax.y * travel;
    sctx.beginPath();
    sctx.arc(kx, ky, knob, 0, Math.PI * 2);
    sctx.fillStyle = "#e8c48a";
    sctx.fill();
    sctx.beginPath();
    sctx.arc(kx, ky, knob * 0.35, 0, Math.PI * 2);
    sctx.fillStyle = INK;
    sctx.fill();
  }

  function drawCrank() {
    const w = crankEl.width, h = crankEl.height, cx = w / 2, cy = h / 2, r = w * 0.42;
    cctx.clearRect(0, 0, w, h);
    cctx.beginPath(); cctx.arc(cx, cy, r + 4, 0, Math.PI * 2);
    cctx.fillStyle = "#2a241e"; cctx.fill();
    cctx.beginPath(); cctx.arc(cx, cy, r, 0, Math.PI * 2);
    cctx.strokeStyle = "#6b5b46"; cctx.lineWidth = 4; cctx.stroke();
    const frac = (leash.len - LEASH_MIN) / (LEASH_MAX - LEASH_MIN);
    cctx.beginPath();
    cctx.arc(cx, cy, r, -Math.PI / 2, -Math.PI / 2 + frac * Math.PI * 2);
    cctx.strokeStyle = TAN; cctx.lineWidth = 5; cctx.stroke();
    cctx.save();
    cctx.translate(cx, cy);
    cctx.rotate(crank.ang);
    cctx.fillStyle = "#e8c48a";
    cctx.beginPath();
    cctx.roundRect(-6, -7, r * 0.95, 14, 7);
    cctx.fill();
    cctx.beginPath(); cctx.arc(r * 0.88, 0, 12, 0, Math.PI * 2); cctx.fill();
    cctx.fillStyle = INK;
    cctx.beginPath(); cctx.arc(0, 0, 6, 0, Math.PI * 2); cctx.fill();
    cctx.restore();
  }

  function fmtClock(sec) {
    const s = Math.max(0, Math.ceil(sec));
    const m = Math.floor(s / 60);
    const r = s % 60;
    return "work in " + m + ":" + (r < 10 ? "0" : "") + r;
  }

  function drawHud() {
    lctx.fillStyle = INK;
    lctx.font = "11px ui-monospace, ui-rounded, system-ui";
    lctx.fillText(fmtClock(clock), 8, 14);

    // pee / poo meters
    const mx = LCD_W - 78, my = 6;
    lctx.fillText("pee", mx, my + 8);
    lctx.strokeStyle = INK;
    lctx.strokeRect(mx + 24, my, 48, 6);
    lctx.fillRect(mx + 24, my, 48 * (didPee ? 0 : pee), 6);
    lctx.fillText("poo", mx, my + 20);
    lctx.strokeRect(mx + 24, my + 12, 48, 6);
    lctx.fillRect(mx + 24, my + 12, 48 * (didPoo ? 0 : poo), 6);

    if (mail > 0) {
      lctx.fillText("MAIL " + mail, 8, 28);
    }

    if (banner) {
      lctx.fillStyle = LIME;
      lctx.fillRect(20, 36, LCD_W - 40, 22);
      lctx.strokeStyle = INK;
      lctx.strokeRect(20, 36, LCD_W - 40, 22);
      lctx.fillStyle = INK;
      lctx.font = "10px ui-monospace, system-ui";
      const tw = lctx.measureText(banner).width;
      const mailImg = stickers["momo-mail"];
      const mailOk = mailImg && stickerReady["momo-mail"] && mailImg.naturalWidth > 0;
      let bx = (LCD_W - tw) / 2;
      if (mailOk) {
        const mh = 14;
        const mw = mh * (mailImg.naturalWidth / mailImg.naturalHeight);
        lctx.imageSmoothingEnabled = false;
        lctx.drawImage(mailImg, Math.max(24, bx - mw - 4), 40, mw, mh);
      }
      lctx.fillText(banner, bx, 51);
    }

    // bag hint
    if (nearPoo(you.x, you.y)) {
      lctx.fillStyle = INK;
      lctx.font = "10px ui-monospace, system-ui";
      lctx.fillText("BAG nearby", 8, LCD_H - 8);
    }

    if (tautPulse > 0) {
      lctx.globalAlpha = Math.min(1, tautPulse);
      lctx.fillStyle = INK;
      lctx.fillRect(0, 0, LCD_W, 2);
      lctx.fillRect(0, LCD_H - 2, LCD_W, 2);
      lctx.globalAlpha = 1;
    }
  }

  function drawEndCard(copy) {
    lctx.fillStyle = LIME;
    lctx.fillRect(0, 0, LCD_W, LCD_H);
    lctx.fillStyle = INK;
    lctx.font = "14px ui-monospace, ui-rounded, system-ui";
    const tw = lctx.measureText(copy).width;
    lctx.fillText(copy, (LCD_W - tw) / 2, 110);
    lctx.font = "11px ui-monospace, system-ui";
    const h = "tap Come/Bag or Enter to walk again";
    const hw = lctx.measureText(h).width;
    lctx.fillText(h, (LCD_W - hw) / 2, 140);
  }

  function drawWorld() {
    if (state === "win") { drawEndCard("Good boy."); return; }
    if (state === "lose") { drawEndCard("He can hold it. You cannot."); return; }
    if (state === "gnome") { drawEndCard("The gnome saw everything."); return; }
    if (state === "dog") { drawEndCard("Tangled. Heel next time."); return; }
    if (state === "leftit") { drawEndCard("You left it."); return; }

    ditherSky();
    drawSidewalk();

    // patches first (far)
    const drawables = [];
    for (const p of patches) {
      const z = worldToCam(p.x, p.y).z;
      if (z > 0.4) drawables.push({ z, draw: () => drawPatch(p) });
    }
    for (const m of mess) {
      const z = worldToCam(m.x, m.y).z;
      if (z > 0.4) drawables.push({ z, draw: () => drawMess(m) });
    }
    for (const p of props) {
      const z = worldToCam(p.x, p.y).z;
      if (z > 0.4) {
        drawables.push({
          z,
          draw: () => {
            const pr = project(p.x, p.y);
            if (!pr) return;
            if (p.kind === "hydrant") drawHydrant(pr);
            else if (p.kind === "tree") drawTree(pr);
            else if (p.kind === "gnome") drawGnome(pr);
            else if (p.kind === "dog") drawDog(pr);
            else if (p.kind === "grandma") drawGrandma(pr);
            else if (p.kind === "home") drawHome(pr);
            else if (p.kind === "porch") drawPorch(pr);
            else if (p.kind === "mailbox") drawMailbox(pr);
            else if (p.kind === "car") drawCar(pr);
            else if (p.kind === "fence") drawFence(pr);
          }
        });
      }
    }
    // unread mail dots
    for (const m of marks) {
      if (m.read) continue;
      const z = worldToCam(m.x, m.y).z;
      if (z > 0.4) {
        drawables.push({
          z,
          draw: () => {
            const pr = project(m.x, m.y);
            if (!pr) return;
            lctx.fillStyle = INK;
            lctx.beginPath();
            lctx.ellipse(pr.x, pr.y, 6, 3, 0, 0, Math.PI * 2);
            lctx.fill();
          }
        });
      }
    }

    drawables.sort((a, b) => b.z - a.z);
    for (const d of drawables) d.draw();

    // leash + momo
    const cam = worldToCam(momo.x, momo.y);
    const handX = LCD_W * 0.5, handY = LCD_H - 2;
    const mp = project(momo.x, momo.y);
    lctx.strokeStyle = INK;
    lctx.lineWidth = 2;
    if (mp) {
      const cx2 = Math.max(-40, Math.min(LCD_W + 40, mp.x));
      const cy2 = mp.y - 6;
      lctx.beginPath();
      lctx.moveTo(handX, handY);
      lctx.lineWidth = 2 + (tautPulse > 0 ? 2 * tautPulse : 0);
      if (leash.taut > 0.5) {
        lctx.lineTo(cx2, cy2);
      } else {
        const sag = 14 * (1 - leash.taut);
        lctx.quadraticCurveTo((handX + cx2) / 2, Math.max(cy2, (handY + cy2) / 2 + sag), cx2, cy2);
      }
      lctx.stroke();
      lctx.lineWidth = 2;
      const scale = Math.max(0.5, Math.min(1.9, 1.5 / Math.max(0.6, cam.z)));
      drawMomo(cx2, Math.min(LCD_H - 20, cy2 + 6), scale);
    } else {
      // off-screen chevron
      const side = cam.x > 0 ? 1 : -1;
      const cx = side > 0 ? LCD_W - 16 : 16;
      const cy = LCD_H - 50;
      lctx.fillStyle = INK;
      lctx.beginPath();
      if (side > 0) {
        lctx.moveTo(cx - 8, cy - 8); lctx.lineTo(cx + 4, cy); lctx.lineTo(cx - 8, cy + 8);
      } else {
        lctx.moveTo(cx + 8, cy - 8); lctx.lineTo(cx - 4, cy); lctx.lineTo(cx + 8, cy + 8);
      }
      lctx.fill();
      lctx.beginPath();
      lctx.moveTo(handX, handY);
      lctx.lineTo(cx, cy);
      lctx.stroke();
    }

    drawHud();
  }

  function fitLcd() {
    const wrap = document.getElementById("lcdWrap");
    const aw = wrap.clientWidth;
    const ah = wrap.clientHeight;
    const scale = Math.max(1, Math.floor(Math.min(aw / LCD_W, ah / LCD_H)));
    lcd.style.width = (LCD_W * scale) + "px";
    lcd.style.height = (LCD_H * scale) + "px";
  }
  addEventListener("resize", fitLcd);
  if (window.visualViewport) visualViewport.addEventListener("resize", fitLcd);
  fitLcd();

  // tap LCD to restart after end
  lcd.addEventListener("pointerdown", () => {
    if (state !== "walking") resetWalk();
  });

  function frame(now) {
    const dt = Math.min(0.05, (now - tPrev) / 1000);
    tPrev = now;
    step(dt);
    drawWorld();
    drawCrank();
    drawStick();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
